def literal_source():
    writes=[];at=2097152
    for ident,value in sorted(LITERALS.items()):
        data=value.encode('utf-8')
        writes += [(8192+16*ident,at),(8192+16*ident+8,len(data))]
        for i in range(0,len(data),8):writes.append((at+i,int.from_bytes(data[i:i+8].ljust(8,b'\0'),'little')))
        at+=(len(data)+7)//8*8
    parts=[];calls=[]
    for group,start in enumerate(range(0,len(writes),96)):
        name='br_data_'+str(group);calls.append('    '+name+'(w)')
        lines=['def '+name+'(w:mutbuf)->u64:']+['    put(w,'+str(offset)+','+str(value)+')' for offset,value in writes[start:start+96]]+['    return 0']
        parts.append('\n'.join(lines))
    parts.append('def br_initialize(w:mutbuf)->u64:\n'+'\n'.join(calls)+'\n    return 0')
    return '\n\n'.join(parts)
def program():
    names={'get','put','choose'}
    helpers=[ast.get_source_segment(PRIMITIVE,n) for n in ast.parse(PRIMITIVE).body if isinstance(n,ast.FunctionDef) and n.name in names]
    source=SOURCE+'\n'+'\n\n'.join(helpers)+'\n'+literal_source()
    for key,value in {**C,**SYMBOLS}.items():source=re.sub(r'\b'+key+r'\b',str(value),source)
    return document(source,'bounded_unroll_receipt')
